 "content": "def transform(grid):
    """Color background cells between horizontally adjacent repeated markers."""
    out = [row[:] for row in grid]
    background = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c] == background and row[c - 1] != background and row[c + 1] == row[c - 1]:
                out[r][c] = 2
    return out
